SELECT id, symbol, interval_code, candle_open_time, generated_at, decision, original_decision, total_score, confidence_score, final_entry_allowed, primary_blocking_stage, confluence_status, confluence_higher_interval, confluence_higher_decision, data_quality_valid, LEFT(final_decision_explanation, 1200) AS final_explanation FROM crypto_ai.trade_signal WHERE id IN (176529, 176655, 176792, 176934, 167746, 159285, 159407) ORDER BY id LIMIT 10;